export const EXAM_QUESTIONS_ES = [
  { id: 0, category: "pas", q: "¿Primer paso del PAS?", opts: ["Avisar","Socorrer","Proteger"], a: 2, expl: "Siempre debes PROTEGERTE a ti y a la víctima antes de hacer nada más." },
  { id: 1, category: "pas", q: "Teléfono emergencias Europa", opts: ["911","091","112"], a: 2, expl: "El 112 es el número único de emergencias en toda la UE." },
  { id: 2, category: "pas", q: "Víctima inconsciente que respira. ¿Posición?", opts: ["Boca arriba","PLS","Sentado"], a: 1, expl: "La PLS evita que la lengua o el vómito obstruyan la vía aérea." },
  { id: 3, category: "rcp", q: "Ritmo RCP adultos", opts: ["60-80 cpm","100-120 cpm","140 cpm"], a: 1, expl: "El ritmo óptimo es rápido, 100-120 compresiones por minuto." },
  { id: 4, category: "rcp", q: "Relación Compresión:Ventilación", opts: ["15:2","30:2","30:5"], a: 1, expl: "30 compresiones seguidas de 2 ventilaciones." },
  { id: 5, category: "hemorragia", q: "¿Qué hacer ante hemorragia nasal?", opts: ["Cabeza atrás","Taponar con algodón","Cabeza adelante y presión"], a: 2, expl: "Inclinar hacia adelante evita tragar sangre." },
  { id: 6, category: "environ", q: "Quemadura: ¿Qué aplicar primero?", opts: ["Pasta dientes","Hielo directo","Agua fría 15 min"], a: 2, expl: "Solo agua fría para enfriar la zona." },
  { id: 7, category: "atragantamiento", q: "Maniobra para atragantamiento grave", opts: ["Heimlich","Rautek","Fowler"], a: 0, expl: "La maniobra de Heimlich desobstruye la vía aérea." },
  { id: 8, category: "enfermedad", q: "Síntoma de anafilaxia", opts: ["Dolor pierna","Hinchazón labios y pitos","Sed"], a: 1, expl: "La anafilaxia es una reacción alérgica severa." },
  { id: 9, category: "enfermedad", q: "Ante convulsión, ¿meter algo en la boca?", opts: ["Sí, un pañuelo","Sí, una cuchara","NUNCA"], a: 2, expl: "Nunca introduzcas nada, podrías causar lesiones." },
  { id: 10, category: "rcp", q: "¿Cuánto profundizar en compresiones torácicas (adulto)?", opts: ["2-3 cm","5-6 cm","8-10 cm"], a: 1, expl: "Se necesita comprimir fuerte (5-6 cm) para bombear sangre." },
  { id: 11, category: "rcp", q: "Si la víctima vomita durante la RCP...", opts: ["Parar y esperar","Poner de lado y limpiar boca","Seguir comprimiendo"], a: 1, expl: "Gírala de lado para limpiar el vómito y luego continúa RCP." },
  { id: 12, category: "rcp", q: "El DEA/DESA sirve para...", opts: ["Desatragantar","Parar hemoragias","Revertir paradas cardiacas"], a: 2, expl: "El desfibrilador administra una descarga para reiniciar el ritmo cardiaco." },
  { id: 13, category: "rcp", q: "Si estás solo con un niño inconsciente que NO respira...", opts: ["Llamar antes de tocar","1 min de RCP y luego llamar","Esperar a ver si respira"], a: 1, expl: "En niños, la causa suele ser respiratoria. Haz RCP un minuto antes de alejarte a llamar." },
  { id: 14, category: "pas", q: "¿Cómo comprobar la consciencia?", opts: ["Pellizcar fuerte","Hablar alto y sacudir hombros","Echar agua"], a: 1, expl: "Estimula verbal y físicamente (hombros) sin ser agresivo." },
  { id: 15, category: "environ", q: "¿Qué NO hacer en una quemadura grave?", opts: ["Romper ampollas","Enfriar con agua","Cubrir con paño limpio"], a: 0, expl: "Las ampollas protegen de infecciones. Nunca las rompas." },
  { id: 16, category: "hemorragia", q: "Objeto clavado en el cuerpo...", opts: ["Sacarlo rápido","Moverlo para ver profundidad","No tocar y fijar"], a: 2, expl: "Si lo sacas, puede aumentar la hemorragia. Inmovilízalo protegiendo alrededor." },
  { id: 17, category: "hemorragia", q: "Torniquete: ¿Cuándo se usa?", opts: ["Siempre que sangra","Hemorragias exanguinantes incontrolables","Picaduras"], a: 1, expl: "Último recurso en extremidades cuando la presión directa no funciona y hay riesgo vital." },
  { id: 18, category: "trauma", q: "Signo de fractura ósea", opts: ["Deformidad y dolor intenso","Picor","Piel seca"], a: 0, expl: "La deformidad, hinchazón y dolor al mover son típicos de fractura." },
  { id: 19, category: "trauma", q: "Esguince: Tratamiento inmediato", opts: ["Calor intenso","Caminar para calentar","Frío, Reposo y Elevación"], a: 2, expl: "Recuerda RICE (Reposo, Hielo, Compresión, Elevación)." },
  { id: 20, category: "trauma", q: "Diente definitivo arrancado (avulsión)", opts: ["Tirarlo","Lavarlo con jabón","Guardar en leche/saliva"], a: 2, expl: "Consérvalo en medio líquido fisiológico y ve urgente al dentista." },
  { id: 21, category: "enfermedad", q: "Lipotimia: ¿Qué hacer?", opts: ["Dar agua rápido","Elevar piernas (Trendelenburg)","Sentarlo"], a: 1, expl: "Elevar las piernas ayuda al retorno venoso al cerebro." },
  { id: 22, category: "environ", q: "Golpe de calor: Primeros auxilios", opts: ["Manta térmica","Enfriar cuerpo gradualmente","Baño helado brusco"], a: 1, expl: "Llevar a un lugar fresco y aplicar paños húmedos." },
  { id: 23, category: "enfermedad", q: "Ictus: Escala CINCINNATI", opts: ["Cara, Brazos, Habla","Dolor pecho","Fiebre alta"], a: 0, expl: "Pide sonreír (Cara), levantar brazos y hablar para detectar Ictus." },
  { id: 24, category: "enfermedad", q: "Infarto: Síntoma común", opts: ["Dolor opresivo en pecho e irradiado","Picor nariz","Hambre"], a: 0, expl: "El dolor suele ir al brazo izquierdo, cuello o mandíbula." },
  { id: 25, category: "environ", q: "Triaje: ¿Quién tiene prioridad?", opts: ["El que más grita","Inconsciente que respira mal","Muerto"], a: 1, expl: "Prioridad Roja: Vida en peligro inmediato pero salvable." },
  { id: 26, category: "environ", q: "¿Qué contiene un botiquín básico?", opts: ["Antibióticos","Bisturí","Gasas, guantes, antiséptico"], a: 2, expl: "Material de cura y autoprotección es lo esencial, no medicación." },
  { id: 27, category: "atragantamiento", q: "Atragantamiento parcial (tose)", opts: ["Golpear espalda","Animar a toser","Heimlich"], a: 1, expl: "Si tose, pasa aire. Deja que el mecanismo natural actúe." },
  { id: 28, category: "enfermedad", q: "Crisis asmática: Posición", opts: ["Tumbado boca abajo","Sentado o semisentado","De pie"], a: 1, expl: "Sentado facilita la respiración. Usa su broncodilatador." },
  { id: 29, category: "enfermedad", q: "Hipoglucemia consciente", opts: ["Insulina","Azúcar/Bebida dulce","Nada por boca"], a: 1, expl: "Necesita azúcar rápido para subir la glucemia." },
  { id: 30, category: "trauma", q: "Si sospechas lesión medular (columna)", opts: ["Mover al hospital","NO mover salvo peligro vital","Sentar cómodo"], a: 1, expl: "Moverlo podría causar parálisis permanente." },
  { id: 31, category: "hemorragia", q: "Herida en tórax \"soplante\"", opts: ["Dejar abierta","Tapar 3 lados (parche valve)","Taponar todo"], a: 1, expl: "Permite salir aire pero no entrar para evitar neumotórax a tensión." },
  { id: 32, category: "hemorragia", q: "Amputación: ¿Qué hacer con el miembro?", opts: ["Agua caliente","Hielo directo","Bolsa estanca y luego hielo"], a: 2, expl: "No pongas el tejido directo en hielo. Protégelo en bolsa primero." },
  { id: 33, category: "environ", q: "Picadura de avispa (sin alergia)", opts: ["Barro","Amoniaco","Frío local y retirar aguijón"], a: 2, expl: "Retira el aguijón rascando (no pinzas) y aplica frío." },
  { id: 34, category: "environ", q: "Mordedura de animal", opts: ["Chupar veneno","Lavar con agua y jabón abundante","Torniquete"], a: 1, expl: "La infección es el mayor riesgo. Lava a fondo." },
  { id: 35, category: "environ", q: "Intoxicación por humo", opts: ["Leche","Salir al aire fresco","Vomitar"], a: 1, expl: "La prioridad es oxigenar. Aléjate de la fuente tóxica." },
  { id: 36, category: "environ", q: "Cuerpo extraño en ojo", opts: ["Frotar fuerte","Lavar con suero/agua abundante","Sacar con pinzas"], a: 1, expl: "El lavado por arrastre es lo más seguro. No frotes." },
  { id: 37, category: "enfermedad", q: "Crisis de ansiedad", opts: ["Respirar en bolsa","Respiración lenta acompañando","Gritarle"], a: 1, expl: "Guía su respiración: \"Inspira... Aguanta... Expulsa\"." },
  { id: 38, category: "rcp", q: "¿Cuándo dejar de hacer RCP?", opts: ["A los 5 min","Cuando llegue ayuda experta o canse","Si rompes costilla"], a: 1, expl: "Continúa hasta que te releven, llegue el 112 o la víctima despierte." },
  { id: 39, category: "enfermedad", q: "Dolor abdominal fuerte y abdomen duro (tabla)", opts: ["Dar laxante","Poner calor","No dar nada y 112"], a: 2, expl: "El abdomen en tabla sugiere irritación peritoneal grave (apendicitis, peritonitis). Requiere cirugía." },
  { id: 40, category: "atragantamiento", q: "Atragantamiento en bebé (< 1 año)", opts: ["Heimlich igual que adulto","5 golpes espalda y 5 compresiones pecho","Sacudir por los pies"], a: 1, expl: "En bebés no se usa Heimlich. Se alternan ciclos de golpes y compresiones torácicas." },
  { id: 41, category: "trauma", q: "Víctima inconsciente con casco (moto)", opts: ["Quitar casco rápido","Dejar casco puesto salvo si no respira","Llenar de agua"], a: 1, expl: "El casco estabiliza. Solo se quita si impide la respiración/RCP y con técnica de dos personas." },
  { id: 42, category: "environ", q: "Herida sucia con tierra", opts: ["Alcohol directo","Agua y jabón chorro","Tapar sin limpiar"], a: 1, expl: "El agua a presión arrastra la suciedad. El alcohol quema el tejido sano." },
  { id: 43, category: "enfermedad", q: "Dificultad respiratoria y sibilancias (pitos)", opts: ["Crisis de ansiedad","Ataque de asma","Infarto"], a: 1, expl: "Los pitos al espirar son típicos del estrechamiento de bronquios en el asma." },
  { id: 44, category: "rcp", q: "¿Cuál es la frecuencia de ventilación en RCP?", opts: ["2 cada 30 compresiones","5 cada 10 compresiones","1 cada 5 compresiones"], a: 0, expl: "Ciclo 30:2 es el estándar internacional para RCP básica." },
  { id: 45, category: "atragantamiento", q: "Señal de atragantamiento completo", opts: ["Grita mucho","No puede hablar, toser ni respirar","Tose con fuerza"], a: 1, expl: "Si no hay sonido, la obstrucción es total. Requiere acción inmediata." },
  { id: 46, category: "pas", q: "Paciente inconsciente boca abajo", opts: ["Dejarlo así","Pasar a PLS con cuidado","Sentarlo"], a: 1, expl: "Boca abajo puede asfixiarse. Poner de lado (PLS) permite vigilar la respiración." },
  { id: 47, category: "rcp", q: "¿Qué es un Desfibrilador (DESA)?", opts: ["Máquina que da masajes","Aparato que analiza y da descarga si falta","Un medidor de tensión"], a: 1, expl: "El DESA analiza el ritmo y solo descarga si hay una fibrilación reversible." },
  { id: 48, category: "environ", q: "Primer paso ante electrocución", opts: ["Tirar del brazo","Cortar la corriente","Echar agua"], a: 1, expl: "NUNCA toques a alguien bajo tensión o te electrocutarás tú también." },
  { id: 49, category: "rcp", q: "¿Cuál es la profundidad de compresión en lactantes?", opts: ["1 cm","4 cm (1/3 tórax)","8 cm"], a: 1, expl: "En lactantes usamos 2 dedos y comprimimos 1/3 del diámetro del tórax (aprox 4cm)." },
  { id: 50, category: "rcp", q: "Ritmo de inflaciones en un ahogado (Parada por asfixia)", opts: ["5 insuflaciones de rescate iniciales","No dar aire, solo masaje","10 insuflaciones seguidas"], a: 0, expl: "En paradas por asfixia (ahogados, niños), el oxígeno es vital, por eso se empieza con 5 ventilaciones." },
  { id: 51, category: "enfermedad", q: "¿Qué hacer ante una convulsión febril en un niño?", opts: ["Darle un baño de agua helada","Poner en PLS, vigilar y refrescar con compresas tibias","Sujetarle fuerte"], a: 1, expl: "Mantén la calma, evita golpes y refresca gradualmente, NO con frío extremo." },
  { id: 52, category: "atragantamiento", q: "Signo de \"atragantamiento incompleto\"", opts: ["La víctima tose con fuerza y habla","No sale ningún sonido","Labios azules"], a: 0, expl: "Si tose, el objeto permite el paso de algo de aire. Animar a toser es lo correcto." },
  { id: 53, category: "enfermedad", q: "¿Qué hacer si una persona tartamudea y tiene la cara torcida de repente?", opts: ["Darle agua con azúcar","Llamar al 112 (sospecha de Ictus)","Dejarle dormir"], a: 1, expl: "Son signos claros de Ictus. Cada minuto cuenta para salvar neuronas." },
  { id: 54, category: "trauma", q: "Ante una fractura abierta (se ve el hueso), ¿qué NO hacer?", opts: ["Poner gasas estériles encima","Intentar meter el hueso dentro","Inmovilizar"], a: 1, expl: "Meter el hueso causaría infecciones graves y daños en tejidos internos." },
  { id: 55, category: "hemorragia", q: "En una amputación, ¿cómo se manda el miembro?", opts: ["Directo en hielo","En bolsa estanca, y esa bolsa dentro de otra con agua y hielo","En un bote con alcohol"], a: 1, expl: "El tejido no debe tocar el agua o hielo directamente para evitar quemaduras por frío." },
  { id: 56, category: "hemorragia", q: "¿Qué es el \"Dedo en Guante\" en hemorragias?", opts: ["Un tipo de venda","Presionar con el dedo directamente dentro de la herida si hay un vaso roto","Ponerse un guante pequeño"], a: 1, expl: "Es la medida más extrema de presión directa sobre un punto sangrante." },
  { id: 57, category: "enfermedad", q: "¿Se puede dar agua a una persona en shock?", opts: ["Sí, mucha","NUNCA, nada por boca","Solo si tiene sed"], a: 1, expl: "En shock, el sistema digestivo no funciona y podría vomitar y aspirar el líquido." },
  { id: 58, category: "rcp", q: "¿Dónde se busca el pulso en un lactante?", opts: ["En el cuello (carotídeo)","En el brazo (braquial)","En la muñeca"], a: 1, expl: "El cuello de un lactante es corto y difícil; el pulso braquial (cara interna del brazo) es más fiable." },
  { id: 59, category: "environ", q: "¿Qué hacer si un objeto está clavado en el ojo?", opts: ["Sacarlo con cuidado","Tapar los DOS ojos y no tocar el objeto","Lavar con chorro de agua fuerte"], a: 1, expl: "Se tapan los dos para que el ojo herido no se mueva (movimiento conjugado) al mirar con el otro." },
  { id: 60, category: "pas", q: "Prioridad de paso en emergencias", opts: ["Llamar al 112","Auto-protección (PAS)","Revisar pulso"], a: 1, expl: "Si no estás a salvo, no puedes ayudar." },
  { id: 61, category: "trauma", q: "¿Qué es la Maniobra de Rautek?", opts: ["Para desatragantar","Para extraer víctimas de un vehículo en peligro","Para curar quemaduras"], a: 1, expl: "Es una técnica para mover a alguien inconsciente protegiendo su eje cabeza-cuello-tronco." },
  { id: 62, category: "trauma", q: "Vendaje en espiral, ¿hacia dónde se venda?", opts: ["De arriba hacia abajo","De la parte más distal (lejos) a la proximal (cerca)","Da igual"], a: 1, expl: "Esto favorece el retorno venoso hacia el corazón." },
  { id: 63, category: "environ", q: "En una quemadura química (ácido), ¿qué hacer?", opts: ["Echar vinagre para neutralizar","Lavar con agua abundante 20-30 min","Tapar con algodón"], a: 1, expl: "El agua arrastra el químico. Neutralizar con otros químicos puede generar calor." },
  { id: 64, category: "enfermedad", q: "¿Qué es una lipotimia?", opts: ["Un paro cardíaco","Un desmayo breve por falta de sangre en el cerebro","Una fractura de cadera"], a: 1, expl: "Es transitorio y se suele recuperar elevando las piernas." },
  { id: 65, category: "rcp", q: "RCP en embarazadas, ¿algún cambio?", opts: ["No se hace RCP","Desplazar el útero a la izquierda durante las compresiones","Comprimir en el abdomen"], a: 1, expl: "Esto evita que el útero presione la vena cava y permita el retorno de sangre." },
  { id: 66, category: "hemorragia", q: "Hemorragia interna sospechosa (golpe fuerte abdomen)", opts: ["Dar masaje","Colocar en posición antishock (piernas arriba) y 112","Dar de beber"], a: 1, expl: "Las hemorragias internas son emergencias críticas invisibles." },
  { id: 67, category: "environ", q: "¿Qué significa el color NEGRO en triaje?", opts: ["Prioridad absoluta","Fallecido o sin esperanza de vida bajo los medios actuales","Herido leve"], a: 1, expl: "En catástrofes, se priorizan recursos para los que tienen posibilidad de sobrevivir." },
  { id: 68, category: "environ", q: "¿Qué hacer ante una sospecha de intoxicación por pastillas?", opts: ["Provocar el vómito siempre","Llevar la caja de pastillas al médico y no provocar vómito sin indicación","Dar leche"], a: 1, expl: "Algunos tóxicos queman al subir si se vomita. La caja ayuda a identificar el antídoto." },
  { id: 69, category: "rcp", q: "Signo de \"muerte clínica\"", opts: ["Cese de respiración y latido","Estar muy pálido","Tener frío"], a: 0, expl: "Es el momento en que se debe iniciar RCP para evitar la muerte biológica." },
  { id: 70, category: "rcp", q: "¿Se puede usar el DESA si llueve?", opts: ["Sí, siempre que el pecho de la víctima esté seco","No, nunca","Solo si hay un paraguas"], a: 0, expl: "Debes secar el tórax rápidamente. No importa si el suelo está húmedo (el parche es bipolar)." },
  { id: 71, category: "rcp", q: "¿Qué es la \"Cadena de Supervivencia\"?", opts: ["Un tipo de nudo","Pasos para aumentar la supervivencia en paro cardíaco","Una medalla"], a: 1, expl: "Aviso precoz, RCP precoz, Desfibrilación precoz y Soporte vital avanzado." },
  { id: 72, category: "rcp", q: "¿Cuántas ventilaciones se dan en un niño después de 30 compresiones?", opts: ["2 ventilaciones","5 ventilaciones","Ninguna"], a: 0, expl: "Aunque se empiece con 5 de rescate, el ciclo se mantiene 30:2 (o 15:2 si son 2 reanimadores)." },
  { id: 73, category: "environ", q: "Hipotermia: ¿Cómo calentar?", opts: ["Frotar manos y pies fuerte","Calentar el tronco gradualmente con mantas","Meter en agua ardiendo"], a: 1, expl: "Calentar extremidades primero puede enviar sangre fría al corazón y pararlo." },
  { id: 74, category: "trauma", q: "Vendaje demasiado apretado, ¿qué ocurre?", opts: ["Sana antes","Compresión nerviosa y falta de riego (dedos azules)","Nada"], a: 1, expl: "Vigila siempre el color y temperatura de los dedos tras vendar." },
  { id: 75, category: "hemorragia", q: "¿Qué hacer ante una herida por arma blanca clavada?", opts: ["Quitar el arma rápido","Fijar el arma para que no se mueva","Limpiar con alcohol"], a: 1, expl: "El objeto clavado hace efecto \"tapón\". Si lo quitas, la hemorragia será masiva." },
  { id: 76, category: "environ", q: "Insolación: ¿Bebida fría o natural?", opts: ["Helada","Natural a sorbos pequeños (si está consciente)","No beber"], a: 1, expl: "Cantidades pequeñas para evitar vómitos. Temperatura ambiente es mejor." },
  { id: 77, category: "pas", q: "¿Qué es el socorrismo?", opts: ["Una profesión deportiva","El deber moral y legal de prestar ayuda","Saber nadar"], a: 1, expl: "Es la primera asistencia que recibe una víctima." },
  { id: 78, category: "enfermedad", q: "¿Qué hacer si un diabético está agresivo y confuso?", opts: ["Llamar a la policía","Darle algo dulce (posible hipoglucemia)","Ignorarlo"], a: 1, expl: "La falta de azúcar en el cerebro altera el comportamiento." },
  { id: 79, category: "enfermedad", q: "¿Qué es la Epistaxis?", opts: ["Sangrado de oído","Sangrado de nariz","Dificultad para tragar"], a: 1, expl: "Proviene del griego \"goteo\" sanguíneo por la nariz." },
  { id: 80, category: "atragantamiento", q: "Obstrucción de vía aérea por lengua", opts: ["Sacar la lengua con pinzas","Maniobra Frente-Mentón","Dar golpes en el cuello"], a: 1, expl: "Extender el cuello eleva la base de la lengua y despeja la garganta." },
  { id: 81, category: "trauma", q: "¿Qué hacer ante un esguince?", opts: ["Mover el tobillo para ver si duele","Frío, Elevación y Reposo","Poner pomada de calor"], a: 1, expl: "El acrónimo RICE (Ice en inglés) es la base inicial." },
  { id: 82, category: "enfermedad", q: "¿Cómo actuar ante un ataque de pánico?", opts: ["Gritar \"¡Cálmate!\"","Pedir que respire al mismo ritmo que tú (lento)","Darle una bofetada"], a: 1, expl: "El acompañamiento y la sincronización respiratoria calman el sistema nervioso." },
  { id: 83, category: "hemorragia", q: "Hemorragia en el cuello, ¿cómo comprimir?", opts: ["Rodeando el cuello con una venda","Presión local con la mano (sin rodear)","No tocar"], a: 1, expl: "Rodear el cuello podría asfixiar a la víctima o cortar el riego al cerebro." },
  { id: 84, category: "pas", q: "Botiquín: ¿Es bueno tener alcohol para las heridas?", opts: ["Sí, desinfecta","No, quema los bordes y retrasa la cura","Solo para quemaduras"], a: 1, expl: "Usa clorhexidina o povidona yodada en su lugar." },
  { id: 85, category: "rcp", q: "¿Qué es un Desfibrilador Semiautomático (DESA)?", opts: ["Uno que hace RCP solo","Uno que analiza el ritmo y te pide pulsar el botón de descarga","Un aparato para ver el pulso"], a: 1, expl: "A diferencia del automático, requiere que el usuario confirme la descarga." },
  { id: 86, category: "trauma", q: "Otorragia (sangre por el oído) tras golpe", opts: ["Taponar el oído con algodón","No taponar y poner de lado sobre el oído que sangra","Limpiar con agua"], a: 1, expl: "Si taponas, aumentas la presión craneal. Dejar salir la sangre es más seguro." },
  { id: 87, category: "enfermedad", q: "¿Cómo se llama la posición de piernas elevadas?", opts: ["Posición de Fowler","Posición de Trendelenburg","Posición de Sims"], a: 1, expl: "Se usa para favorecer el riego cerebral en desmayos." },
  { id: 88, category: "atragantamiento", q: "¿Qué hacer si un niño se traga un objeto pequeño pero respira?", opts: ["Hacerle el Heimlich","Llevar a urgencias sin intentar sacarlo uno mismo","Darle de comer miga de pan"], a: 1, expl: "Si no hay obstrucción total, intentar sacarlo puede empujarlo y bloquear la vía aérea." },
  { id: 89, category: "pas", q: "Distancia para colocar triángulos de emergencia", opts: ["10 metros","50 metros","200 metros"], a: 1, expl: "Deben ser visibles al menos desde 100 metros de distancia." },
  { id: 90, category: "environ", q: "¿Qué hacer ante una herida punzante con un clavo oxidado?", opts: ["Lavar e ir al médico para vacuna del Tétanos","Solo lavar","Poner una tirita"], a: 0, expl: "El tétanos es una enfermedad grave que entra por heridas sucias o profundas." },
  { id: 91, category: "pas", q: "¿Qué es la \"Hora de Oro\"?", opts: ["La hora de comer","El tiempo crítico tras un accidente donde la atención médica salva vidas","Un premio"], a: 1, expl: "Las posibilidades de supervivencia caen drásticamente después de 60 minutos." },
  { id: 92, category: "rcp", q: "Compresiones torácicas: ¿Brazos doblados o rectos?", opts: ["Doblados","Rectos aprovechando el peso del cuerpo","Da igual"], a: 1, expl: "Doblar los codos cansa rápido y la presión no es vertical." },
  { id: 93, category: "rcp", q: "¿Qué hacer si el DESA dice \"No se recomienda descarga\"?", opts: ["Apagarlo","Continuar con la RCP 30:2 inmediatamente","Retirar los parches"], a: 1, expl: "El DESA volverá a analizar en 2 minutos. No pares la RCP." },
  { id: 94, category: "hemorragia", q: "¿Cómo reconocer una hemorragia arterial?", opts: ["Rojo oscuro y sale despacio","Rojo brillante y sale a chorros rítmicos","Solo gotea"], a: 1, expl: "La sangre arterial sale a presión pulsátil por el latido del corazón." },
  { id: 95, category: "environ", q: "¿Qué hacer ante una picadura de medusa?", opts: ["Lavar con agua dulce","Lavar con agua de mar y quitar restos con pinzas o tarjeta","Echar arena caliente"], a: 1, expl: "El agua dulce activa las células urticantes (nematocistos) que no han explotado." },
  { id: 96, category: "trauma", q: "¿Qué hacer ante un golpe en el ojo con un balón?", opts: ["Hielo directo","Compresa fría sin presionar y revisión médica","Echar colirio"], a: 1, expl: "Puede haber lesiones internas de retina aunque no se vea sangre." },
  { id: 97, category: "rcp", q: "Sujeto inconsciente que \"ronca\" o respira muy mal", opts: ["Está durmiendo","Es una respiración agónica, tratar como parada cardíaca (RCP)","Poner la radio"], a: 1, expl: "El \"gasping\" no es respirar. Es un signo de muerte inminente." },
  { id: 98, category: "hemorragia", q: "Vaso roto por corte de cristal: ¿Prioridad?", opts: ["Llamar familiar","Presión directa sobre el corte","Limpiar el suelo"], a: 1, expl: "Detener la pérdida de sangre es vital." },
  { id: 99, category: "pas", q: "¿Qué es la \"Omisión del deber de socorro\"?", opts: ["No saber hacer RCP","Un delito por no ayudar o pedir ayuda si alguien está en peligro","Un seguro médico"], a: 1, expl: "La ley obliga a ayudar o llamar al 112 si no sabemos cómo actuar." },
  { id: 100, category: "enfermedad", q: "¿Cómo actuar ante un parto inminente?", opts: ["Intentar frenarlo","Poner a la madre en un lugar limpio, tranquilo y dejar que ocurra naturalmente","Tirar del bebé"], a: 1, expl: "El parto es un proceso natural. Tu labor es Higiene, Calma y Apoyo." },
  { id: 101, category: "environ", q: "¿Se debe lavar una quemadura con leche?", opts: ["Sí, alivia","No, nunca. Solo agua fresca","Si es de sol sí"], a: 1, expl: "La leche puede causar infecciones. El agua es lo único seguro." },
  { id: 102, category: "enfermedad", q: "Persona con dolor de pecho que se va al brazo izquierdo: ¿Sospecha?", opts: ["Gases","Infarto agudo de miocardio","Esguince"], a: 1, expl: "El dolor irradiado al brazo, cuello o mandíbula es un signo clásico." },
  { id: 103, category: "trauma", q: "¿Qué es el Signo de Battle (hematoma tras oreja)?", opts: ["Para RCP","Indica fractura de base de cráneo","Para vendar"], a: 1, expl: "Es un signo médico (Equimosis mastoidea) tras traumatismos graves." },
  { id: 104, category: "environ", q: "¿Qué hacer si un químico salta a la piel?", opts: ["Poner vinagre","Lavar con agua corriente al menos 20 min","Echar polvos"], a: 1, expl: "El agua diluye y elimina el químico por arrastre." },
  { id: 105, category: "atragantamiento", q: "Si una persona se ha ahorcado, ¿primer paso?", opts: ["Llamar al 112","Sostener su cuerpo y cortar la ligadura rápido","Hacer fotos"], a: 1, expl: "La falta de aire mata en pocos minutos. Hay que bajar a la víctima inmediatamente." },
  { id: 106, category: "hemorragia", q: "¿Cómo reconocer un choque (shock) hipovolémico?", opts: ["Pulso lento y fuerte","Pulso rápido, débil y piel fría/sudorosa","Mucha hambre"], a: 1, expl: "El cuerpo intenta compensar la falta de sangre acelerando el motor." },
  { id: 107, category: "environ", q: "¿Qué hacer ante una mordedura de serpiente?", opts: ["Hacer un corte y chupar el veneno","Inmovilizar, tranquilizar e ir a urgencias","Poner un torniquete"], a: 1, expl: "Chupar el veneno o hacer cortes aumenta el daño y la infección." },
  { id: 108, category: "rcp", q: "¿Se puede usar el DESA en un niño de 4 años?", opts: ["No, solo adultos","Sí, preferiblemente con parches pediátricos (o modo niño)","Solo si respira"], a: 1, expl: "El DESA es seguro en niños; si no hay parches de niño, pueden usarse los de adulto." },
  { id: 109, category: "atragantamiento", q: "¿Qué hacer si alguien se atraganta con un caramelo y tose?", opts: ["Golpes en la espalda","Animar a toser fuerte","Meter los dedos"], a: 1, expl: "Si tose, el objeto se está moviendo. Los golpes podrían encajarlo más." },
  { id: 110, category: "pas", q: "¿Qué es la \"Muerte Encefálica\"?", opts: ["Estar inconsciente","Cese irreversible de todas las funciones cerebrales","Dormir profundo"], a: 1, expl: "Es el criterio legal de fallecimiento aunque el corazón lata artificialmente." },
  { id: 111, category: "environ", q: "¿Cómo tratar una ampolla por quemadura solar?", opts: ["Explotarla con una aguja","No tocarla y cubrir con gasa estéril si hay riesgo de roce","Echar alcohol"], a: 1, expl: "El líquido de la ampolla es un apósito natural que evita infecciones." },
  { id: 112, category: "rcp", q: "¿Cuál es la frecuencia de compresiones en un niño (1 reanimador)?", opts: ["15 compresiones : 2 ventilaciones","30 compresiones : 2 ventilaciones","Solo compresiones"], a: 1, expl: "Si estás solo, el ritmo es igual que en adultos (30:2)." },
  { id: 113, category: "enfermedad", q: "¿Qué es el síncope?", opts: ["Un paro cardíaco","Una pérdida de conocimiento súbita y completa con recuperación rápida","Un tipo de venda"], a: 1, expl: "Es lo mismo que un desmayo." },
  { id: 114, category: "pas", q: "En un accidente de tráfico, ¿a quién atiendes el último?", opts: ["El que no grita ni se mueve","El que grita mucho","El que tiene un corte leve"], a: 2, expl: "Primero se atiende a los críticos salvables (rojos), luego urgentes (amarillos) y por último leves (verdes)." },
  { id: 115, category: "enfermedad", q: "¿Qué hacer si una persona convulsiona por epilepsia?", opts: ["Ponerle un palo en la boca","Quitar objetos cercanos con los que pueda golpearse","Sujetarle los brazos"], a: 1, expl: "Tu objetivo es evitar que se lesione durante los movimientos involuntarios." },
  { id: 116, category: "trauma", q: "¿Cómo mover a una persona si sospechas lesión de cuello?", opts: ["Tirando de los pies","En bloque (varios socorristas manteniendo el eje recto)","No se puede mover"], a: 1, expl: "Si hay peligro vital (fuego), muévelo como si fuera un tronco rígido." },
  { id: 117, category: "trauma", q: "¿Qué es el \"Reflejo de Babinski\"?", opts: ["Un tipo de RCP","Una respuesta del pie que indica daño neurológico en adultos","Curar una quemadura"], a: 1, expl: "Es normal en bebés, pero anormal en adultos tras un golpe en la cabeza." },
  { id: 118, category: "environ", q: "¿Qué hacer ante una intoxicación por lejía?", opts: ["Beber leche o agua","No provocar el vómito y llamar al 112","Vomitar rápido"], a: 1, expl: "Los corrosivos queman al bajar y volverían a quemar al subir si se vomita." },
  { id: 119, category: "trauma", q: "¿Cómo reconocer una fractura de cadera?", opts: ["La pierna parece más larga","La pierna está acortada y hacia afuera","No duele"], a: 1, expl: "Es la posición típica por la tracción muscular tras la rotura." },
  { id: 120, category: "rcp", q: "Persona encontrada en la nieve inconsciente: ¿Prioridad?", opts: ["Darle alcohol para calentar","Secar, poner mantas y buscar signos de vida (RCP si no hay)","Frotar la piel"], a: 1, expl: "El alcohol baja más la temperatura real del cuerpo aunque dé calor subjetivo." },
  { id: 121, category: "trauma", q: "¿Qué es la \"Triada de la Muerte\" en trauma?", opts: ["Fuego, Agua, Aire","Acidosis, Hipotermia y Coagulopatía","No respirar, no pulso, no consciencia"], a: 1, expl: "Son tres factores que se retroalimentan y matan a la víctima de trauma si no se controlan." },
  { id: 122, category: "trauma", q: "¿Qué hacer si un objeto está clavado en el abdomen?", opts: ["Sacarlo rápido","Fijarlo y no dejar que se mueva","Lavar el objeto"], a: 1, expl: "Al igual que en otras zonas, sacarlo puede provocar una hemorragia incontrolable." },
  { id: 123, category: "trauma", q: "¿Cómo saber si un vendaje está muy apretado?", opts: ["Si el paciente tiene calor","Si los dedos se ponen fríos, azulados o con hormigueo","Si se cae"], a: 1, expl: "Indica falta de riego sanguíneo." },
  { id: 124, category: "trauma", q: "¿Qué son los \"Ojos de Mapache\"?", opts: ["Una alergia","Hematomas alrededor de los ojos tras golpe en cabeza (posible fractura de cráneo)","Cansancio"], a: 1, expl: "Es signo de fractura en la base del cráneo." },
  { id: 125, category: "pas", q: "¿Se puede dar comida a alguien que ha sufrido un accidente grave?", opts: ["Sí, para que tenga energía","NUNCA, por si requiere cirugía urgente","Solo pan"], a: 1, expl: "El estómago debe estar vacío para la anestesia en una posible operación." },
  { id: 126, category: "trauma", q: "¿Qué es la \"Posición Antálgica\"?", opts: ["La que adopta la víctima para sentir menos dolor","Ponerse boca abajo","Estar de pie"], a: 0, expl: "Respeta esa posición si no es peligrosa, ya que el cuerpo de la víctima sabe cómo protegerse." },
  { id: 127, category: "pas", q: "¿Cómo actuar ante un pinchazo con aguja usada en la calle?", opts: ["Lavar con agua y jabón e ir al hospital para análisis","No hacer nada","Poner alcohol"], a: 0, expl: "Hay riesgo de transmisión de enfermedades (VIH, Hepatitis)." },
  { id: 128, category: "rcp", q: "¿Qué hacer si una persona tiene un infarto y deja de respirar?", opts: ["Llamar al 112 y empezar RCP","Esperar a la ambulancia","Sentarlo"], a: 0, expl: "Cada segundo sin RCP disminuye las posibilidades de vida un 10%." },
  { id: 129, category: "rcp", q: "¿Qué es el DESA?", opts: ["Aparato para respirar","Desfibrilador Externo Semiautomático","Un tipo de camilla"], a: 1, expl: "Dispositivo que puede salvar vidas en paradas por fibrilación." },
  { id: 130, category: "enfermedad", q: "¿Cómo reconocer un Ictus?", opts: ["Dolor de estómago","Boca torcida, dificultad al hablar, pérdida de fuerza en un brazo","Fiebre"], a: 1, expl: "Recordamos TEST: Cara, Brazo, Habla, Tiempo." },
  { id: 131, category: "hemorragia", q: "¿Qué es el torniquete?", opts: ["Una venda suave","Dispositivo para comprimir una arteria y detener hemorragia masiva","Un tipo de nudo"], a: 1, expl: "Se usa solo en hemorragias incontrolables en extremidades." },
  { id: 132, category: "environ", q: "¿Qué hacer si alguien se quema con aceite hirviendo?", opts: ["Poner mantequilla","Lavar con agua fría 10-15 minutos","Tapar con una manta"], a: 1, expl: "El agua detiene la progresión del calor en la piel." },
  { id: 133, category: "enfermedad", q: "¿Qué es la Reacción Vagovagal?", opts: ["Un infarto","Un desmayo por bajada de tensión (miedo, calor, visión de sangre)","Un ataque de ira"], a: 1, expl: "Es la causa más común de lipotimias." },
  { id: 134, category: "atragantamiento", q: "¿Cómo actuar ante un atragantamiento por objeto circular (ej: moneda)?", opts: ["Meter el dedo para sacarlo","Maniobra de Heimlich","Poner boca abajo"], a: 1, expl: "La presión del aire de los pulmones expulsará el objeto." },
  { id: 135, category: "hemorragia", q: "¿Qué hacer si una persona tiene un corte que sangra mucho en la pierna?", opts: ["Poner hielo","Presión directa con gasas o paño limpio","Dejar al aire"], a: 1, expl: "La presión es el método más efectivo para detener la sangre." },
  { id: 136, category: "trauma", q: "¿Qué es la fractura en tallo verde?", opts: ["Huesos de plantas","Fractura incompleta común en niños (el hueso se dobla)","Un tipo de golpe"], a: 1, expl: "Los huesos de los niños son más flexibles y no rompen del todo." },
  { id: 137, category: "trauma", q: "¿Qué hacer ante una hemorragia por el oído?", opts: ["Taponar con gasa","Poner de lado sobre el lado que sangra y no taponar","Lavar con agua"], a: 1, expl: "Puede indicar fractura de cráneo; taponar aumentaría la presión cerebral." },
  { id: 138, category: "pas", q: "¿Qué es el Pulso?", opts: ["La respiración","La onda de presión de la sangre al ser bombeada por el corazón","Un dolor de cabeza"], a: 1, expl: "Es la medida rítmica de la actividad cardiaca." },
  { id: 139, category: "rcp", q: "¿Cuál es la profundidad de RCP en adultos?", opts: ["2 cm","Entre 5 y 6 cm","10 cm"], a: 1, expl: "Es la profundidad necesaria para que el masaje sea eficaz." },
  { id: 140, category: "atragantamiento", q: "¿Qué hacer si una persona consciente se atraganta y no puede hablar?", opts: ["Darle agua","Realizar la maniobra de Heimlich","Esperar"], a: 1, expl: "Si no puede hablar ni toser, la obstrucción es total." },
  { id: 141, category: "hemorragia", q: "¿Cómo tratar una hemorragia de nariz?", opts: ["Echar cabeza atrás","Pinzar la nariz e inclinar cabeza adelante","Acostarse"], a: 1, expl: "Evita tragar sangre y facilita la coagulación." },
  { id: 142, category: "environ", q: "¿Qué hacer ante la presencia de un rayo?", opts: ["Ponerse bajo un árbol","Ponerse en posición de cuclillas con pies juntos lejos de metal","Correr"], a: 1, expl: "Minimizas tu altura y los puntos de contacto con el suelo." },
  { id: 143, category: "trauma", q: "Señal de Fractura de Clavícula", opts: ["Hombro caído y brazo sujetado por el otro","Dolor de espalda","Hipo"], a: 0, expl: "El paciente suele adoptar esta posición para aliviar el dolor." },
  { id: 144, category: "pas", q: "¿Qué es la Escala de Glasgow?", opts: ["Para medir el peso","Mide el nivel de consciencia (3 a 15)","Para medir la vista"], a: 1, expl: "Valora respuesta ocular, verbal y motora." },
  { id: 145, category: "environ", q: "¿Cómo actuar ante un náufrago con hipotermia?", opts: ["Darle café muy caliente","Cambiar ropa mojada por seca y calentar suavemente","Hacerle correr"], a: 1, expl: "El calentamiento debe ser gradual para no dañar el sistema circulatorio." },
  { id: 146, category: "pas", q: "¿Qué hacer si la víctima de accidente tiene frío intenso?", opts: ["Encender una estufa cerca","Tapar con manta térmica o ropa","No hacer nada"], a: 1, expl: "Mantener la temperatura corporal es crucial para la supervivencia." },
  { id: 147, category: "trauma", q: "Signo de \"Muñeca en péndulo\"", opts: ["Lesión de nervio por fractura","Un juego","Cansancio"], a: 0, expl: "La pérdida de control motor indica daño en nervios cercanos a la fractura." },
  { id: 148, category: "enfermedad", q: "¿Qué hacer en caso de ataque de asma si no hay medicación?", opts: ["Hacerle correr para abrir pulmones","Llamar al 112, tranquilizar y posición sentada","Darle de comer"], a: 1, expl: "La posición sentada ayuda a usar los músculos accesorios de la respiración." },
  { id: 149, category: "pas", q: "¿Cómo se cura una herida por roce?", opts: ["Limpiar con agua y jabón y dejar al aire si no sangra mucho","Tapar con barro","No tocar"], a: 0, expl: "La limpieza previene la infección, que es el mayor riesgo en roces." },
  { id: 150, category: "environ", q: "¿Qué hacer si alguien respira veneno (gas)?", opts: ["Echar agua en la cara","Sacar a la víctima al aire libre y llamar al 112","Vomitar"], a: 1, expl: "La prioridad es alejar de la fuente tóxica." },
  { id: 151, category: "pas", q: "Diferencia entre Urgencia y Emergencia", opts: ["Son lo mismo","En la emergencia hay riesgo vital inmediato","La urgencia es más grave"], a: 1, expl: "La emergencia requiere actuación en pocos minutos para salvar la vida." },
  { id: 152, category: "environ", q: "¿Qué hacer ante una quemadura eléctrica?", opts: ["Echar pomada","Ir al hospital aunque no parezca grave (daños internos)","Lavar"], a: 1, expl: "La electricidad daña órganos internos (corazón, riñones) aunque la piel parezca bien." },
  { id: 153, category: "hemorragia", q: "¿Cómo actuar ante una herida en la cabeza?", opts: ["Presionar con gasas y vendar","Lavar con mucho alcohol","Mover mucho la cabeza"], a: 0, expl: "Las heridas en la cabeza sangran mucho; la presión es fundamental." },
  { id: 154, category: "trauma", q: "¿Qué hacer si sospechas lesión de cuello en un bañista?", opts: ["Sacarlo rápido del pelo","Mantener en flotación con cabeza alineada hasta ayuda","Hacerle nadar"], a: 1, expl: "El agua ayuda a mantener el peso, pero el eje cuello-columna debe estar recto." },
  { id: 155, category: "rcp", q: "¿Qué es la \"Muerte Súbita\"?", opts: ["Quedarse dormido","Paro cardíaco inesperado en persona aparentemente sana","Un desmayo"], a: 1, expl: "Suele deberse a una arritmia maligna." },
  { id: 156, category: "trauma", q: "¿Cómo tratar un golpe fuerte en la espalda?", opts: ["Dar masaje","Inmovilizar y vigilar sensibilidad en piernas","Caminar"], a: 1, expl: "Cualquier hormigueo o pérdida de fuerza indica daño en la médula." },
  { id: 157, category: "enfermedad", q: "¿Qué hacer si un niño tiene fiebre alta y no para de llorar?", opts: ["Darle un baño de agua fría","Consultar al médico y refrescar suavemente","Esperar al día siguiente"], a: 1, expl: "El agua tibia es mejor que la fría para evitar shocks térmicos." },
  { id: 158, category: "pas", q: "¿Qué es el socorrista?", opts: ["Cualquier persona que ayuda en una emergencia","Solo los médicos","Los que llevan uniforme"], a: 0, expl: "Eres tú en el momento en que decides actuar y ayudar." },
  { id: 159, category: "pas", q: "Símbolo de la Cruz Roja", opts: ["Un círculo","Una cruz sobre fondo blanco","Un cuadrado"], a: 1, expl: "Es el emblema internacional de protección médica." },
  { id: 160, category: "enfermedad", q: "¿Qué hacer ante una crisis diabética si no sabes si es alta o baja?", opts: ["Dar insulina siempre","Dar un poco de azúcar (si está consciente)","No hacer nada"], a: 1, expl: "Si es baja, el azúcar le salva. Si es alta, un poco más no le hará daño inmediato." },
  { id: 161, category: "trauma", q: "¿Qué hacer si alguien tiene un calambre muscular fuerte?", opts: ["Estirar el músculo suavemente en dirección contraria","Gritar al músculo","No tocar"], a: 0, expl: "El estiramiento pasivo alivia la contracción involuntaria." },
  { id: 162, category: "hemorragia", q: "¿Cómo identificar una hemorragia venosa?", opts: ["Sangre roja brillante a chorros","Sangre roja oscura que fluye de forma continua","Solo gotea"], a: 1, expl: "La sangre venosa tiene menos presión y menos oxígeno." },
  { id: 163, category: "pas", q: "¿Qué hacer si una persona ha caminado mucho y tiene ampollas?", opts: ["Explotarlas todas","Limpiar y proteger con apósito especial (segunda piel)","No hacer nada"], a: 1, expl: "Evita el dolor y el riesgo de infección por roce." },
  { id: 164, category: "pas", q: "¿Qué es el Pulso Carotídeo?", opts: ["El de la muñeca","El que se toma en el cuello a los lados de la nuez","El del pie"], a: 1, expl: "Es el más fácil de encontrar en víctimas inconscientes." },
  { id: 165, category: "enfermedad", q: "¿Qué hacer si una persona tiene una convulsión febril?", opts: ["Meterle agua helada","Tumbar de lado y refrescar con agua tibia","Sujetar fuerte"], a: 1, expl: "Las convulsiones febriles asustan pero suelen ser breves e inofensivas si se evita el golpe." },
  { id: 166, category: "pas", q: "¿Se puede usar el móvil mientras atiendes?", opts: ["Para jugar","Para hablar con el 112 en manos libres","No se puede"], a: 1, expl: "El operador del 112 te guiará paso a paso mientras actúas." },
  { id: 167, category: "pas", q: "¿Cuál es la primera regla del socorrismo?", opts: ["Correr mucho","No causar más daño (No ser otra víctima)","Saber medicina"], a: 1, expl: "\"Primum non nocere\": primero, no dañar." },
  { id: 168, category: "hemorragia", q: "¿Qué hacer si alguien tiene un objeto clavado en la mano?", opts: ["Retirarlo y poner alcohol","No retirarlo y vendar alrededor fijándolo","Lavar el objeto"], a: 1, expl: "El objeto clavado ayuda a controlar la hemorragia interna." },
  { id: 169, category: "hemorragia", q: "¿Cómo actuar ante un golpe en la nariz con sangre?", opts: ["Echar agua oxigenada","Presionar la nariz y cabeza hacia adelante","Poner algodón con fuerza"], a: 1, expl: "La presión directa sobre el tabique nasal corta la mayoría de sangrados." },
  { id: 170, category: "rcp", q: "¿Qué es la Reanimación Cardiopulmonar?", opts: ["RCP","Un tipo de carrera","Un masaje de espalda"], a: 0, expl: "Serie de maniobras para mantener la vida ante un paro." },
  { id: 171, category: "enfermedad", q: "¿Qué hacer si una persona se desmaya por calor?", opts: ["Llevar a la sombra y elevar piernas","Darle agua caliente","Dejarle al sol"], a: 0, expl: "Ayuda a enfriar y recuperar la tensión arterial." },
  { id: 172, category: "environ", q: "¿Se debe usar pasta de dientes en quemaduras?", opts: ["Sí, refresca","NUNCA, es un error común que infecta","Solo si no hay agua"], a: 1, expl: "Usa solo agua corriente." },
  { id: 173, category: "environ", q: "¿Qué hacer si una persona tiene una descarga eléctrica y sigue pegada al cable?", opts: ["Tocarla para apartarla","Separar el cable con un objeto de madera o plástico (aislante)","Echar agua"], a: 1, expl: "Debes usar algo que no conduzca la electricidad para no electrocutarte." },
  { id: 174, category: "trauma", q: "¿Qué es el Hematoma?", opts: ["Un tipo de sangre","Acumulación de sangre bajo la piel tras un golpe (moratón)","Una herida abierta"], a: 1, expl: "Indica rotura de pequeños vasos sanguíneos sin rotura de piel." },
  { id: 175, category: "trauma", q: "¿Cómo actuar ante una luxación (hueso fuera de sitio)?", opts: ["Intentar colocar el hueso","Inmovilizar y llevar al médico","Mover para ver si encaja"], a: 1, expl: "Colocarlo mal puede dañar nervios y arterias de forma permanente." },
  { id: 176, category: "enfermedad", q: "¿Qué hacer ante una intoxicación alimentaria?", opts: ["Dar laxantes","Hidratación y vigilar signos de alarma (deshidratación)","Comer mucho"], a: 1, expl: "Reponer líquidos es lo más importante en diarreas y vómitos." },
  { id: 177, category: "atragantamiento", q: "¿Qué es la Vía Aérea?", opts: ["Un camino por el aire","El conducto por donde entra el aire a los pulmones","Una carretera"], a: 1, expl: "Mantenerla despejada es la prioridad #1." },
  { id: 178, category: "rcp", q: "¿Qué hacer si una persona inconsciente NO respira?", opts: ["Esperar 10 minutos","Llamar al 112 y realizar RCP inmediatamente","Ponerle una manta"], a: 1, expl: "La vida de la persona depende de tus manos en ese momento." },
  { id: 179, category: "pas", q: "¿Qué es el triaje?", opts: ["Un tipo de vendaje","Sistema de clasificación de víctimas según gravedad","Una receta"], a: 1, expl: "Permite optimizar el orden de atención en catástrofes." },
  { id: 180, category: "enfermedad", q: "¿Cómo reconocer una anafilaxia?", opts: ["Dolor de pies","Piel roja, hinchazón de cara y dificultad para respirar","Hambre"], a: 1, expl: "Requiere inyección de adrenalina urgente." },
  { id: 181, category: "enfermedad", q: "¿Qué hacer si una persona tiene un ataque de epilepsia en el agua?", opts: ["Dejarla","Sujetar la cabeza por encima del agua hasta que pase la crisis","Sacarla rápido tirando del cuello"], a: 1, expl: "Evita el ahogamiento mientras dura la convulsión." },
  { id: 182, category: "environ", q: "¿Qué hacer ante un gran incendio con humo?", opts: ["Caminar erguido","Ir a ras de suelo (donde hay más oxígeno)","Correr hacia arriba"], a: 1, expl: "El humo sube; el aire más respirable está cerca del suelo." },
  { id: 183, category: "pas", q: "¿Cómo ayudar a una persona en silla de ruedas en una emergencia?", opts: ["Apartarla","Preguntar cómo prefiere ser ayudada antes de moverla","Llevarla a pulso rápido"], a: 1, expl: "La persona conoce mejor su movilidad y equipo." },
  { id: 184, category: "environ", q: "¿Qué hacer ante una picadura de abeja si el aguijón está dentro?", opts: ["Retirar con pinzas apretando","Retirar rascando con una tarjeta de crédito o uña","Dejarlo"], a: 1, expl: "Al usar pinzas puedes apretar el saco de veneno y meter más tóxico." },
  { id: 185, category: "pas", q: "¿Qué es el botiquín?", opts: ["Una caja de herramientas","Conjunto de materiales necesarios para la primera atención","Una farmacia"], a: 1, expl: "Debe estar revisado y ser accesible." },
  { id: 186, category: "environ", q: "¿Qué hacer si te entra un químico en el ojo?", opts: ["Frotar fuerte","Lavar con agua abundante durante 20 minutos sin parar","Tapar el ojo"], a: 1, expl: "El lavado continuo diluye el químico y lo saca del ojo." },
  { id: 187, category: "atragantamiento", q: "¿Qué hacer si una embarazada se atraganta?", opts: ["Maniobra de Heimlich normal en abdomen","Compresiones torácicas (en el centro del pecho)","Golpes en la barriga"], a: 1, expl: "Hay que evitar presionar el abdomen para no dañar al bebé." },
  { id: 188, category: "pas", q: "¿Cómo actuar ante un curioso grabando con el móvil?", opts: ["Quitarle el móvil","Pedirle que guarde el móvil y ayudar si puede o alejarse","Ponerse a grabar también"], a: 1, expl: "Hay que respetar la privacidad y seguridad de la escena." },
  { id: 189, category: "enfermedad", q: "¿Qué hacer si una persona dice que tiene \"sed de aire\"?", opts: ["Llamar al 112, está en insuficiencia respiratoria","Darle de beber","Hacerle soplar fuerte"], a: 0, expl: "Es una sensación subjetiva de ahogo grave." },
  { id: 190, category: "hemorragia", q: "¿Qué es un torniquete neumático?", opts: ["Uno manual","Uno que se infla como el manguito de tensión","Un tipo de zapato"], a: 1, expl: "Permite un control más preciso de la presión sobre el brazo o pierna." },
  { id: 191, category: "enfermedad", q: "¿Cómo actuar ante una mordedura humana?", opts: ["Reírse","Lavar muy bien con agua y jabón y vigilar infección médica","No hacer nada"], a: 1, expl: "La boca humana tiene muchas bacterias peligrosas." },
  { id: 192, category: "hemorragia", q: "¿Qué hacer si sospechas una hemorragia por el recto (sangre roja)?", opts: ["Dar laxante","Ir a urgencias para descartar hemorroides o daño interno","Dar agua"], a: 1, expl: "Cualquier pérdida de sangre por orificios naturales debe valorarse." },
  { id: 193, category: "trauma", q: "¿Qué es el \"Dedo en resorte\" (o gatillo)?", opts: ["Un tipo de RCP","Cuando un dedo se queda bloqueado al doblar","Un dedo roto"], a: 1, expl: "Es una inflamación de los tendones." },
  { id: 194, category: "trauma", q: "¿Qué hacer si una persona se corta con un cristal y un trozo queda dentro?", opts: ["Sacarlo con los dientes","No sacarlo y cubrir para que no se mueva","Lavar el cristal dentro"], a: 1, expl: "Si lo sacas tú, podrías causar una hemorragia mayor." },
  { id: 195, category: "environ", q: "¿Qué hacer ante una insolación?", opts: ["Dar agua fría a sorbos y poner en sitio fresco","Dar un café caliente","Correr"], a: 0, expl: "Ayuda a rehidratar y bajar la temperatura corporal." },
  { id: 196, category: "pas", q: "¿Cómo saber si alguien está en coma?", opts: ["Si está muy dormido","Si no responde a estímulos dolorosos ni habla","Si ronca"], a: 1, expl: "Es un nivel de consciencia muy bajo que requiere atención vital." },
  { id: 197, category: "pas", q: "¿Qué hacer si una víctima dice que no quiere que la ayudes (pero está en peligro)?", opts: ["Ayudar a la fuerza","Llamar al 112 y quedarse cerca vigilando por si pierde el conocimiento","Irte"], a: 1, expl: "Si pierde el conocimiento o su juicio está alterado, el consentimiento es implícito." },
  { id: 198, category: "pas", q: "¿Qué es el corazón?", opts: ["Un órgano emocional","Un músculo que bombea sangre a todo el cuerpo","Una caja"], a: 1, expl: "Sin su bombeo la vida cesa en minutos." }
];

